import OpenAI from "openai";

export const openai = new OpenAI({
  apiKey: process.env.OPENAI_API_KEY,
  baseURL: process.env.OPENAI_BASE_URL,
});

export async function chat(
  messages: OpenAI.Chat.ChatCompletionMessageParam[],
  model = "gpt-4o-mini",
): Promise<string> {
  const response = await openai.chat.completions.create({ model, messages });
  return response.choices[0]?.message?.content ?? "";
}

export async function embed(text: string): Promise<number[]> {
  const response = await openai.embeddings.create({
    model: "text-embedding-3-small",
    input: text,
  });
  return response.data[0]?.embedding ?? [];
}

postInstallNotes:
The platform automatically injects a proxied OpenAI key when no `OPENAI_API_KEY` is present, so your app can make real AI calls right away (rate-limited to 100 req/day). Add your own key in the Secrets tab to remove the rate limit.

```ts
import { chat } from "./lib/openai";
const reply = await chat([{ role: "user", content: "Hello!" }]);
```
